const ABBR: Record<string,string> = {alleycats:"IND",apex:"COL",bighorns:"LV",breeze:"DC",cascades:"SEA",empire:"NY",flyers:"CAR",glory:"BOS",growlers:"SD",havoc:"HOU",hustle:"ATL",phoenix:"PHI",radicals:"MAD",royal:"MTL",rush:"TOR",shred:"SLC",sol:"ATX",spiders:"OAK",steel:"ORE",thunderbirds:"PIT",union:"CHI",windchill:"MIN"};
const f=(x:number,d=2)=>Number(x).toFixed(d);
const signed=(x:number,d=1)=>(x>0?"+":"")+f(x,d);
const interval=(a:any,d=2)=>a ? f(a[0],d)+" to "+f(a[1],d) : "Not estimable";
const val=(r:any,key:string,mode:string)=>mode==="change"?r.change[key]:r.stages[mode==="first"?0:1][key];
const ci=(r:any,key:string,mode:string)=>mode==="change"?r.change_ci95[key]:r.stages[mode==="first"?0:1].ci95[key];
function axis(values:number[],includeZero:boolean){
  let lo=Math.min(...values),hi=Math.max(...values);
  if(includeZero){lo=Math.min(lo,0);hi=Math.max(hi,0);}
  const pad=(hi-lo)*.13||1;lo-=pad;hi+=pad;
  const raw=(hi-lo)/6,pow=Math.pow(10,Math.floor(Math.log10(raw)));
  const step=([1,2,2.5,5,10].find(a=>a*pow>=raw)||10)*pow;
  lo=Math.floor(lo/step)*step;hi=Math.ceil(hi/step)*step;
  const ticks=[];for(let x=lo;x<=hi+step*.01;x+=step)ticks.push(x);
  return {lo,hi,ticks};
}
function Scatter({rows,xKey,yKey,mode,correlation,selected,onSelect}:any){
  const t=useHostTheme(), left=82,right=910,top=30,bottom=430;
  const xs=rows.map((r:any)=>val(r,xKey,mode)),ys=rows.map((r:any)=>val(r,yKey,mode));
  const ax=axis(xs,mode==="change"),ay=axis(ys,mode==="change");
  const X=(v:number)=>left+(v-ax.lo)/(ax.hi-ax.lo)*(right-left);
  const Y=(v:number)=>bottom-(v-ay.lo)/(ay.hi-ay.lo)*(bottom-top);
  const count=(r:any)=>r.stages[mode==="first"?0:1].possessions;
  const maxN=Math.max(...rows.map(count)),rad=(n:number)=>Math.sqrt(n/maxN)*11;
  const placed:any[]=[];
  const pts=rows.map((r:any)=>({r,x:X(val(r,xKey,mode)),y:Y(val(r,yKey,mode))}));
  const labels=pts.map((p:any)=>{
    let chosen:any,best=Infinity;
    for(const [dx,dy] of [[13,-11],[13,19],[-40,-11],[-40,19],[10,-23],[-40,30],[16,4],[-45,4]]){
      const box={x:p.x+dx,y:p.y+dy-12,w:28,h:15};
      let penalty=0;
      for(const q of placed)if(box.x<q.x+q.w&&box.x+box.w>q.x&&box.y<q.y+q.h&&box.y+box.h>q.y)penalty+=100;
      for(const q of pts)if(q.x>box.x-5&&q.x<box.x+box.w+5&&q.y>box.y-5&&q.y<box.y+box.h+5)penalty+=20;
      if(box.x<left||box.x+box.w>right||box.y<top||box.y+box.h>bottom)penalty+=500;
      if(penalty<best){best=penalty;chosen={...box,tx:p.x+dx,ty:p.y+dy};}
    }
    placed.push(chosen);return {...p,label:chosen};
  });
  let x1=ax.lo,x2=ax.hi;
  const m=correlation.slope,b=correlation.intercept;
  if(m!==0){const a=(ay.lo-b)/m,c=(ay.hi-b)/m;x1=Math.max(x1,Math.min(a,c));x2=Math.min(x2,Math.max(a,c));}
  const xLabel=mode==="change"?"Change in huck attempt percentage (percentage points)":"Huck attempt percentage (%)";
  const yLabel=yKey==="scoring"?"Change in scoring percentage (percentage points)":mode==="change"?"Change in mean throws per possession":"Mean physical throws per possession";
  return <div style={{overflowX:"auto"}}>
    <svg viewBox="0 0 960 510" style={{display:"block",width:"100%",minWidth:620}} role="img" aria-label={xLabel+" versus "+yLabel+". Each dot is a team."}>
      <title>{xLabel+" versus "+yLabel}</title>
      {ax.ticks.map((tick:number)=><g key={"x"+tick}><line x1={X(tick)} x2={X(tick)} y1={top} y2={bottom} stroke={tick===0&&mode==="change"?t.text.secondary:t.stroke.tertiary} strokeDasharray={tick===0&&mode==="change"?"4 4":undefined}/><text x={X(tick)} y={bottom+26} textAnchor="middle" fontSize="12" fill={t.text.secondary}>{f(tick,Number.isInteger(tick)?0:1)}</text></g>)}
      {ay.ticks.map((tick:number)=><g key={"y"+tick}><line x1={left} x2={right} y1={Y(tick)} y2={Y(tick)} stroke={tick===0&&mode==="change"?t.text.secondary:t.stroke.tertiary} strokeDasharray={tick===0&&mode==="change"?"4 4":undefined}/><text x={left-13} y={Y(tick)+4} textAnchor="end" fontSize="12" fill={t.text.secondary}>{f(tick,Number.isInteger(tick)?0:1)}</text></g>)}
      <line x1={X(x1)} y1={Y(m*x1+b)} x2={X(x2)} y2={Y(m*x2+b)} stroke={t.text.secondary} strokeWidth="1.5" strokeDasharray="5 5"/>
      {labels.map(({r,x,y,label}:any)=><g key={r.team} role="button" tabIndex={0} aria-label={r.team_name+"; select team"} onClick={()=>onSelect(r.team)} onKeyDown={(e:any)=>{if(e.key==="Enter"||e.key===" ")onSelect(r.team);}} style={{cursor:"pointer"}}>
        <circle data-team={r.team} data-x={val(r,xKey,mode)} data-y={val(r,yKey,mode)} cx={x} cy={y} r={rad(count(r))} fill={selected===r.team?t.accent.primary:t.text.secondary} opacity={selected===r.team?1:.72}/>
        {selected===r.team&&<circle cx={x} cy={y} r={rad(count(r))+4} fill="none" stroke={t.accent.primary} strokeWidth="1.3"/>}
        <text x={label.tx} y={label.ty} fill={selected===r.team?t.accent.primary:t.text.primary} fontWeight={selected===r.team?650:450} fontSize="12">{ABBR[r.team]}</text>
        <title>{r.team_name+"\n"+xLabel+": "+f(val(r,xKey,mode))+"\n"+yLabel+": "+f(val(r,yKey,mode))+"\nFirst / second possessions: "+r.stages[0].possessions+" / "+r.stages[1].possessions+"\nX 95% interval: "+interval(ci(r,xKey,mode))+"\nY 95% interval: "+interval(ci(r,yKey,mode))}</title>
      </g>)}
      <text x={(left+right)/2} y={bottom+66} textAnchor="middle" fontSize="14" fill={t.text.primary}>{xLabel}</text>
      <text transform="translate(23 230) rotate(-90)" textAnchor="middle" fontSize="14" fill={t.text.primary}>{yLabel}</text>
    </svg>
    <Text size="small" tone="secondary">Dot area represents {mode==="first"?"first":"second"} possessions. Dashed line: descriptive linear fit across 22 teams. Select a dot to inspect its counts and 95% ranges.</Text>
  </div>;
}
function Sources(){
  return <details><summary>Definitions, source coverage and uncertainty</summary><Stack gap={10} style={{paddingTop:12}}>
    <Text size="small">Source: preserved ShownSpace export and audited UFA raw events. April 24–July 19, 2026 regular season; 131 captured games, 22 teams. Pittsburgh at Chicago on July 18 is missing. This is an archived analysis, not a live refresh.</Text>
    <Text size="small">Only the receiving team’s first and exactly second possession in a point are compared. The recorded original seven must remain throughout. Keep all eligible openings, including those never followed by a regain. Exclude possessions with a timeout, period endings, uncertain or changed lineups, and previously reviewed special clock situations. Eligible zero-throw possessions remain in scoring and mean throw count.</Text>
    <Text size="small">Huck: endpoint distance greater than 40 yards AND forward gain greater than 30 yards. Huck attempt percentage = 100 × huck attempts / all physical throw attempts. Scoring percentage = 100 × goals / goal-or-turnover possessions. Mean throws = physical attempts / possessions. Completions, drops, throwaways and centering passes count as attempts; no automatic centering deduction is applied.</Text>
    <Text size="small">The same eligible possessions supply both axes. Long-field starts are at least 60 yards from goal at the first recorded throwing location, not the verified pickup spot. This broad filter does not exactly match field position. Source checks omit 29 invalid receiving points; five otherwise eligible first/second possessions lack a starting location. Reviewed end-of-quarter exclusions are incomplete coverage, not a full clock screen.</Text>
    <Text size="small">Pearson r gives every team equal weight. Its 95% range resamples whole games 10,000 times, keeping both teams and stages together. It describes sampling uncertainty for this fixed set of teams, not causality or a prediction. Draws with unestimable team rates are omitted; intervals are suppressed if fewer than 95% of draws remain. Team ranges are individual, not simultaneous. Spearman checks whether the ordering agrees without requiring a linear relationship.</Text>
    <Text size="small">Subsequent possessions are conditional on losing and regaining the disc. Starting position, opponent, defensive pressure and other context can differ. The plot cannot establish that hucking changes scoring, or that fatigue or impatience caused the observed patterns.</Text>
    <Text size="small">Calculations and row-level membership are preserved under research/possession_relationships. Existing review labels and published research counts are unchanged.</Text>
  </Stack></details>;
}

export default function HuckShareAndThrowCount(){
  const t=useHostTheme(),[scope,setScope]=useState("long_field"),[mode,setMode]=useState("change"),[outcome,setOutcome]=useState("all"),[selected,setSelected]=useState("union");
  const data=DATA.scopes[scope][outcome],rel=data.correlations["hucking_vs_throws_"+mode];
  const team=data.teams.find((r:any)=>r.team===selected)||data.teams[0],a=data.league.stages[0],b=data.league.stages[1];
  return <article style={{maxWidth:1160,margin:"0 auto",padding:"28px 24px",color:t.text.primary}}><Stack gap={18}>
    <Text size="small" tone="secondary">SEPARATE QUESTION · HUCK SHARE AND THROW COUNT</Text>
    <H1>Higher huck share accompanies fewer throws</H1>
    <Text>The relationship is negative in both first and second possessions. But these measures share total throws, so part of the relationship is built into the arithmetic.</Text>
    <div style={{display:"flex",gap:18,flexWrap:"wrap"}}>
      <label>Comparison <Select value={mode} onChange={setMode} options={[{value:"change",label:"Change · second minus first"},{value:"first",label:"First possessions only"},{value:"second",label:"Second possessions only"}]}/></label>
      <label>Possession outcome <Select value={outcome} onChange={setOutcome} options={[{value:"all",label:"Goals and turnovers"},{value:"goal",label:"Goals only"},{value:"turnover",label:"Turnovers only"}]}/></label>
      <label>Starting location <Select value={scope} onChange={setScope} options={[{value:"long_field",label:"At least 60 yards from goal"},{value:"all_starts",label:"All known starts"}]}/></label>
    </div>
    <div style={{display:"flex",gap:28,flexWrap:"wrap",borderTop:"1px solid "+t.stroke.tertiary,borderBottom:"1px solid "+t.stroke.tertiary,padding:"16px 0"}}>
      <div><Text size="small" tone="secondary">TEAM CORRELATION</Text><H2>r = {f(rel.pearson)}</H2></div>
      <div><Text size="small" tone="secondary">95% GAME-BOOTSTRAP RANGE</Text><H2>{rel.ci95?interval(rel.ci95):"Too sparse for a stable range"}</H2></div>
      <div><Text size="small" tone="secondary">RANK CORRELATION</Text><H2>ρ = {f(rel.spearman)}</H2></div>
    </div>
    <Text size="small">{mode==="change"?"Right = huck share rises after the regain. Down = mean throws per possession falls.":"Each team is compared within the same possession stage; first and second possessions are not pooled into one correlation."} {a.possessions.toLocaleString()} first and {b.possessions.toLocaleString()} second possessions in this filter.</Text>
    <Scatter rows={data.teams} xKey="hap" yKey="mean_throws" mode={mode} correlation={rel} selected={selected} onSelect={setSelected}/>
    <section style={{borderLeft:"3px solid "+t.accent.primary,paddingLeft:18}}><Stack gap={8}>
      <H2>{team.team_name}</H2>
      <Text>Huck share: {f(team.stages[0].hap,1)}% → {f(team.stages[1].hap,1)}%. Mean throws: {f(team.stages[0].mean_throws,2)} → {f(team.stages[1].mean_throws,2)} per possession.</Text>
      <Text size="small" tone="secondary">{team.stages[0].possessions} first / {team.stages[1].possessions} second possessions. Displayed X 95% range: {interval(ci(team,"hap",mode),2)} {mode==="change"?"percentage points":"percent"}. Displayed Y range: {interval(ci(team,"mean_throws",mode),2)} throws.</Text>
    </Stack></section>
    <H2>The denominator explains part of the pattern</H2>
    <Text><strong>Huck share × mean throws = hucks per possession</strong>, when huck share is written as a decimal. If hucks per possession stay similar, fewer total throws automatically produce a higher huck percentage.</Text>
    <Table headers={["Pooled league measure","First possession","Second possession"]} columnAlign={["left","right","right"]} rows={[["Huck attempt percentage",f(a.hap,2)+"%",f(b.hap,2)+"%"],["Mean physical throws / possession",f(a.mean_throws,2),f(b.mean_throws,2)],["Hucks / possession",f(a.hucks_per_possession,3),f(b.hucks_per_possession,3)],["Possessions",a.possessions,b.possessions]]}/>
    <Text>For long-field starts with both outcomes included, hucks per possession change only from 0.422 to 0.440, while mean throws fall from 8.17 to 6.23. “More hucks” and “a greater percentage of throws being hucks” are different claims.</Text>
    <Text size="small" tone="secondary">Goals and turnovers can have different possession lengths. The outcome filter separates them descriptively; it does not prove the effect of choosing a huck. Short possessions can end in quick scores or quick turnovers. Centering passes remain counted.</Text>
    <details><summary>Every team’s counts and rates</summary><Stack gap={14} style={{paddingTop:12}}>
      <Table headers={["Team","First n","Second n","HAP first (%)","HAP second (%)","Throws first","Throws second","Hucks/pos first","Hucks/pos second"]} columnAlign={["left","right","right","right","right","right","right","right","right"]} rows={data.teams.map((r:any)=>[r.team_name,r.stages[0].possessions,r.stages[1].possessions,f(r.stages[0].hap),f(r.stages[1].hap),f(r.stages[0].mean_throws),f(r.stages[1].mean_throws),f(r.stages[0].hucks_per_possession,3),f(r.stages[1].hucks_per_possession,3)])}/>
      <Text size="small">Valid correlation bootstrap draws: {rel.valid_bootstrap.toLocaleString()} / 10,000. {rel.ci_note}</Text>
    </Stack></details>
    <Text size="small" tone="secondary">Source: preserved ShownSpace + audited UFA events · April 24–July 19, 2026 regular season · original seven · same completed possessions for both measures.</Text>
    <Sources/>
  </Stack></article>;
}

